-- Rock the Arena shared meet-night model. All competition records are explicitly simulated.
create table public.meet_events (id uuid primary key default gen_random_uuid(), title text not null, status text not null default 'upcoming' check(status in ('upcoming','live','completed')), current_rotation integer not null default 1 check(current_rotation between 1 and 4), simulated_flag boolean not null default true, created_at timestamptz not null default now());
create table public.meet_challenges (id uuid primary key default gen_random_uuid(), meet_id uuid not null references public.meet_events(id) on delete cascade, rotation_number integer not null check(rotation_number between 1 and 4), challenge_type text not null, question text not null, options jsonb not null, correct_answer text not null, explanation text not null, points integer not null default 100, active_status boolean not null default false, simulated_flag boolean not null default true);
create table public.challenge_attempts (id uuid primary key default gen_random_uuid(), meet_id uuid not null references public.meet_events(id) on delete cascade, fan_id uuid references auth.users(id) on delete set null, challenge_id uuid not null references public.meet_challenges(id) on delete cascade, submitted_answer text not null, correct boolean not null, points_awarded integer not null default 0, created_at timestamptz not null default now(), unique(fan_id, challenge_id));
create table public.fan_point_balances (fan_id uuid not null references auth.users(id) on delete cascade, meet_id uuid not null references public.meet_events(id) on delete cascade, total_points integer not null default 0, completed_challenges integer not null default 0, primary key(fan_id,meet_id));
create table public.card_unlocks (id uuid primary key default gen_random_uuid(), fan_id uuid references auth.users(id) on delete cascade, athlete_id uuid references public.athletes(id) on delete set null, meet_id uuid references public.meet_events(id) on delete set null, unlock_source text not null, unlocked_at timestamptz not null default now(), unique(fan_id,athlete_id,meet_id));
create table public.crowd_milestones (id uuid primary key default gen_random_uuid(), meet_id uuid not null references public.meet_events(id) on delete cascade, target integer not null, current_progress integer not null default 0, reward_type text not null, reward_content text not null, completed boolean not null default false);
create table public.engagement_events (id uuid primary key default gen_random_uuid(), meet_id uuid references public.meet_events(id) on delete cascade, fan_id uuid references auth.users(id) on delete set null, event_type text not null, entity_id text, simulated_flag boolean not null default true, created_at timestamptz not null default now());
alter table public.meet_events enable row level security; alter table public.meet_challenges enable row level security; alter table public.challenge_attempts enable row level security; alter table public.fan_point_balances enable row level security; alter table public.card_unlocks enable row level security; alter table public.crowd_milestones enable row level security; alter table public.engagement_events enable row level security;
create policy "read simulated meets" on public.meet_events for select using(simulated_flag); create policy "read simulated challenges" on public.meet_challenges for select using(simulated_flag); create policy "read simulated milestones" on public.crowd_milestones for select using(true);
